package com.example.data.model

import androidx.room.Entity
import androidx.room.Index
import androidx.room.PrimaryKey

/**
 * Stores individual predictions generated by each model across all betting markets:
 * 1X2, Over/Under 2.5, Over/Under 1.5, BTTS (Both Teams To Score), Double Chance.
 */
@Entity(
    tableName = "predictions",
    indices = [
        Index(value = ["fixtureId", "modelId", "market"], unique = true),
        Index(value = ["modelId", "isCorrect"]),
        Index(value = ["roundId"])
    ]
)
data class PredictionEntity(
    @PrimaryKey(autoGenerate = true)
    val id: Long = 0,
    val fixtureId: String,
    val roundId: String,
    val fixture: String,
    val modelId: String,
    val modelVersion: String = "1.0",
    val market: String, // "1X2", "O/U 2.5", "O/U 1.5", "BTTS", "DC"
    val predictedSelection: String, // e.g. "1", "Over 2.5", "Under 2.5", "BTTS Yes", "1X"
    val confidence: Double, // 0.0 to 1.0
    val oddsAtPrediction: Double,
    val isCorrect: Boolean? = null, // null = pending match result, true = won, false = lost
    val predictedUtc: String,
    val settledUtc: String? = null
)
